Polymorphisme
Même interface, comportements différents.

class Document:
    def __init__(self, title):
        self.title = title

    def display(self):
        raise NotImplementedError

class Book(Document):
    def display(self):
        return f"Livre: {self.title}"

class Magazine(Document):
    def display(self):
        return f"Magazine: {self.title}"

# Test polymorphique
documents = [
    Book("1984"),
    Magazine("National Geographic")
]

for doc in documents:
    print(doc.display())

Livre: 1984
Magazine: National Geographic

@staticmethod - Méthodes utilitaires
Méthodes sans accès à l’instance ou la classe.

class LibraryUtils:
    @staticmethod
    def format_isbn(isbn):
        """Formatage ISBN sans besoin de l'instance"""
        return f"{isbn[:3]}-{isbn[3:4]}-{isbn[4:9]}-{isbn[9:12]}-{isbn[12]}"

isbn = "9782070368228"
formatted = LibraryUtils.format_isbn(isbn)
print(f"ISBN formaté : {formatted}")

ISBN formaté : 978-2-07036-822-8


Quand l’utiliser : - Fonctions utilitaires liées conceptuellement à la classe - Pas besoin de self ou cls

@classmethod - Méthodes de classe
Méthodes avec accès à la classe (pas l’instance).

class Book:
    total_count = 0

    def __init__(self, title):
        self.title = title
        Book.total_count += 1

    @classmethod
    def from_dict(cls, data):
        """Factory method - constructeur alternatif"""
        return cls(data['title'])

    @classmethod
    def get_total_count(cls):
        return cls.total_count

book1 = Book("1984")
book2 = Book.from_dict({'title': 'Dune'})
print(f"Nombre total de livres : {Book.get_total_count()}")

Nombre total de livres : 2


Avantages : - Constructeurs alternatifs (factory methods) - Accès aux variables de classe - Utile pour le tracking

@abstractmethod - Classes abstraites
Forcer l’implémentation dans les sous-classes.

from abc import ABC, abstractmethod

class Borrowable(ABC):
    @abstractmethod
    def borrow(self):
        pass

    @abstractmethod
    def return_item(self):
        pass

class Book(Borrowable):
    def __init__(self, title):
        self.title = title
        self.available = True

    def borrow(self):
        if not self.available:
            raise Exception(f"Le livre '{self.title}' n'est pas disponible")
        self.available = False
        return f"Livre '{self.title}' emprunté"

    def return_item(self):
        self.available = True
        return f"Livre '{self.title}' retourné"

book = Book("1984")
print(book.borrow())
print(book.return_item())

Livre '1984' emprunté
Livre '1984' retourné


Avantages : - Contrat d’interface clair - Erreurs à la création, pas à l’exécution - Documentation du comportement attendu

O - Open/Closed Principle
Principe : Ouvert à l’extension, fermé à la modification.

